-- Milestone achievements: generic metric/threshold definitions evaluated by the badge service.
ALTER TABLE community_badge_definitions ADD COLUMN metric TEXT;
ALTER TABLE community_badge_definitions ADD COLUMN threshold INTEGER;
ALTER TABLE community_badge_definitions ADD COLUMN sort_order INTEGER NOT NULL DEFAULT 0;
UPDATE community_badge_definitions SET metric='xp',threshold=250,sort_order=20 WHERE key='community_level_5';
UPDATE community_badge_definitions SET metric='xp',threshold=1000,sort_order=21 WHERE key='community_level_10';
UPDATE community_badge_definitions SET metric='xp',threshold=4000,sort_order=22 WHERE key='community_level_20';
UPDATE community_badge_definitions SET sort_order=10 WHERE key='discord_linked';
UPDATE community_badge_definitions SET sort_order=30 WHERE key='server_booster';
UPDATE community_badge_definitions SET sort_order=40 WHERE key='first_work';
UPDATE public_catalog_clock SET revision=lower(hex(randomblob(16))) WHERE id=1;
